import {createTradeGame,reduceTrade,quoteOrder,rebookShipping,forecastCash,parseTradeSave,PRODUCTS,SUPPLIERS,SHIPPING,UPGRADES,MARKETS,capacity,weeklyCost,netWorth,infrastructureAssets,upgradeCost,unlockedMarkets,fxRateAt,PAYMENT_TERMS,MANAGERS,expansionCost,expansionWeekly,LIFE_ITEMS,COMPANIONS,lifeItemCost,lifeReserve,nextTradeEvent,europeanTrackRecord} from './trade-economy.js';
const KEY='trade-tycoon:data:v2';
const app=document.querySelector('#trade-app'),dialog=document.querySelector('#trade-dialog');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>(v<0?'−':'')+'¥'+Math.abs(Math.round(v||0)).toLocaleString('zh-CN');
const usd=cents=>'US$'+(Number(cents||0)/100).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
const fxRate=rate=>(Number(rate||0)/10000).toFixed(4);
const compact=v=>Math.abs(v)>=10000?(v/10000).toFixed(1)+'万':Math.round(v).toLocaleString('zh-CN');
const byId=(items,id)=>items.find(x=>x.id===id);
let state=null,tab='desk',notice='',saveWarning='',timer,quoteId=null,quoteOptions={supplier:'reliable',shipping:'sea',markup:0,fxMode:'locked',paymentTerms:'standard'},importCandidate=null,importTicket=0,damagedSave=null;
let legacyAvailable=false,lastReceipt=null,lastAdvance=null,lifeOpen=false;
let advisorOpen=false,routeOrderId=null,endingFresh=false;
const focusedOrders=new Set(); // Session-only intent, scoped to one existing contract through collection.
let guideReplay=false,guideHidden=false;try{guideHidden=localStorage.getItem(KEY+':guide-hidden')==='yes';}catch{}
function firstOrderGuide(){
 if(guideHidden||(!guideReplay&&state.metrics.orders>state.receivables.length))return button('重看首单指引','guide-show','','small guide-replay');
 if(state.metrics.orders>0)return `<section class="first-guide"><b>${state.receivables.length?'交付完成，还有尾款待收':'第一笔生意跑通了！'}</b><span>${state.receivables.length?'在回执里展开待收尾款即可跟进，也可以点码头票据。':'已交付的货款都已到账，可以比较下一单了。'}</span>${button('我会了','guide-hide','','small')}</section>`;
 const o=state.active[0],r=state.receivables[0],step=o?(o.paidShipping?3:2):r?4:1;
 const text={1:['先挑一笔生意','看预计利润和多久收齐钱，点一张生意卡。先不用研究其他数字。'],2:['签下了，订金已入账','货物正在备好。下一步出运，日期和支出会按合同推进。有可用换班时，可以先比较。'],3:['货已经出发','跟进这批货到交付。普通询盘会随日期更新。'],4:['交付成功，等尾款回来','利润不等于到账的钱。再推进到回款，完成第一轮。']}[step];
 return `<section class="first-guide"><span class="guide-step">${step}/4</span><div><b>${text[0]}</b><p>${text[1]}</p></div>${step>1?button(o?(o.paidShipping?'看这批货交付 →':'让这批货出运 →'):'等这笔尾款到账 →','follow-order',`data-id="${esc((o||r).id)}"`,'primary'):''}${o&&!o.paidShipping&&!o.shippingRevision&&['sea','rail'].some(id=>rebookShipping(state,o.id,id).valid)?button('先看运费与船期','route-plan',`data-id="${esc(o.id)}"`,'small'):''}${button('跳过指引','guide-hide','','small')}</section>`;
}
const dayLabel=d=>'第 '+d+' 天';
const recordDay=r=>r.day??((r.week-1)*7+1);
function advanceFeedback(){
 if(!lastAdvance)return '';
 const p=lastAdvance.pause,summary=lastAdvance.summary||{},details=[];
 if(summary.payments)details.push('出运支出 '+money(summary.payments));
 if(summary.operating)details.push('运营及利息 '+money(summary.operating));
 if(summary.fxAdjustment)details.push('此前尾款汇差 '+money(summary.fxAdjustment));
 if(lastAdvance.expiredOffers)details.push('询盘已更新');
 return `<section class="notice ${p?'warning':''} advance-feedback" role="status"><div><strong>已推进 ${lastAdvance.advancedDays} / ${lastAdvance.requestedDays} 天 · 当前${dayLabel(state.day)}</strong>${details.length?`<p>${details.join(' · ')}</p>`:''}${p?`<p>${esc(p.message)}${lastAdvance.requestedDays>lastAdvance.advancedDays?' 剩余 '+(lastAdvance.requestedDays-lastAdvance.advancedDays)+' 天未推进。':''}</p>`:''}</div>${lastAdvance.remainingDays>0&&(p?.code==='offers_expiring'||p?.code==='funding_gap')?button('确认后继续','advance-review','','small'):''}</section>`;
}

try{legacyAvailable=!!(localStorage.getItem('trade-tycoon:v1')||localStorage.getItem('trade-tycoon:standalone:v1'));const raw=localStorage.getItem(KEY);if(raw){try{const loaded=parseTradeSave(raw);const original=JSON.parse(raw);if(original.ruleset!==loaded.ruleset&&!localStorage.getItem(KEY+':before-upgrade'))localStorage.setItem(KEY+':before-upgrade',raw);state=loaded;}catch{damagedSave=raw;saveWarning='经营存档暂时无法读取，未覆盖。请先导出原文件留存。';}}}catch{saveWarning='浏览器无法读写存档。请定期导出，避免关闭后丢失进度。';}
// Persist before switching the UI. Do not mutate either game or its schema.
function replaceTradeRun(storage,key,current,next){
 const previous=JSON.stringify(current),replacement=JSON.stringify(next);
 storage.setItem(key+':before-new-game',previous);
 // Web Storage setItem is atomic: a quota/security failure retains the old value.
 storage.setItem(key,replacement);
}

function save(){if(damagedSave)return;try{localStorage.setItem(KEY,JSON.stringify(state));saveWarning='';}catch{saveWarning='自动保存失败，请到「账本」导出存档。';}}
function download(text,name){const url=URL.createObjectURL(new Blob([text],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
// One read-only path for all recovery exports; original keys and bytes stay intact.
const savedRunExports={
 'export-previous':[':before-new-game','贸易经营-上局存档.json','尚未重新开局，没有上局存档。','浏览器无法读取上局存档。'],
 'export-upgrade':[':before-upgrade','贸易经营-升级前存档.json','尚无升级前备份，当前进度可正常导出。','浏览器无法读取升级前存档。'],
 'export-backup':[':before-import','贸易经营-导入前备份.json','尚无导入前备份，当前进度可正常导出。','浏览器无法读取备份。']
};
function exportSavedRun(suffix,filename,missing,error){
 try{
  const raw=localStorage.getItem(KEY+suffix);
  if(raw)download(raw,filename);
  else toast(missing);
 }catch{toast(error);}
}
function toast(message){clearTimeout(timer);const el=document.querySelector('#trade-toast');el.textContent=message;el.classList.add('show');timer=setTimeout(()=>el.classList.remove('show'),4500);}
const button=(label,action,attrs='',cls='')=>`<button class="${cls}" data-action="${action}" ${attrs}>${label}</button>`;
function chart(values,labels=[],label='资金曲线',fromZero=true,format=money,axisFormat=compact,padding=5){
 const list=values.length?values:[0,0];const lo=fromZero?Math.min(...list,0):Math.max(0,Math.min(...list)-padding),hi=fromZero?Math.max(...list,1):Math.max(...list)+padding,span=hi-lo||1;
 const x=i=>30+i*270/Math.max(1,list.length-1),y=v=>15+(hi-v)/span*70;
 const points=list.map((v,i)=>`${x(i)},${y(v)}`).join(' '),zero=y(0);
 return `<svg class="chart" viewBox="0 0 330 110" role="img" aria-label="${esc(label)}：${list.map(format).join('，')}" preserveAspectRatio="none"><path class="axis" d="M30 15H300M30 50H300M30 85H300"/><polygon class="area" points="30,85 ${points} 300,85"/><polyline class="line" points="${points}"/><circle cx="${x(list.length-1)}" cy="${y(list.at(-1))}" r="3" fill="#186583"/>${lo<0?`<path class="zero" d="M30 ${zero}H300"/>`:''}<text x="0" y="19">${axisFormat(hi)}</text><text x="0" y="88">${axisFormat(lo)}</text>${labels.map((l,i)=>i===0||i===labels.length-1||i===Math.floor(labels.length/2)?`<text x="${x(i)}" y="106" text-anchor="${i===0?'start':i===labels.length-1?'end':'middle'}">${esc(l)}</text>`:'').join('')}</svg>`;
}
// Original product line drawings; presentation only, no economic state.
function productArt(id){const paths={fasteners:'M8 9l7-4 7 4v8l-7 4-7-4z M15 10v6 M12 13h6 M23 20l5 5 M24 18l6 6 M20 24l5 5',cups:'M11 8h14v22H11z M13 4h10v4 M14 13h8 M14 17h8 M16 25h4',lights:'M12 22c0-4-5-6-5-12a11 11 0 0122 0c0 6-5 8-5 12z M12 26h12 M14 30h8 M15 10l3 4 3-4 M18 14v8',tools:'M5 8h18l7 5v6H18l-3 11H8l3-13H5z M30 11h4v10h-4 M7 11h7',textiles:'M5 9l8-5 5 5 5-5 8 5-5 8-4-3v16H14V14l-4 3z M14 23h8',pumps:'M8 16h18v12H8z M11 11h12v5 M15 6h4v5 M26 18h6v7h-6 M4 28h26 M12 20h10 M12 24h10'};return `<svg class="product-art" viewBox="0 0 36 36" aria-hidden="true" focusable="false"><path d="${paths[id]||paths.fasteners}"/></svg>`;}
function shipArt(){return `<svg viewBox="0 0 400 220" aria-hidden="true"><circle cx="305" cy="50" r="30" fill="#f5a341"/><path d="M25 145H360L327 185H78Z" fill="#dce6eb"/><path d="M45 130H250V145H45Z" fill="#4b7993"/><path d="M73 103H127V129H73ZM132 103H186V129H132ZM191 103H245V129H191Z" fill="#e87936"/><path d="M108 74H162V101H108ZM167 74H221V101H167Z" fill="#f5a341"/><path d="M267 105H322V145H267ZM278 84H311V105H278Z" fill="#f7fafb"/><path d="M23 199H375M57 210H300" stroke="#7aa2b9" stroke-width="2"/><path d="M33 95V26H203M35 28L132 95M155 28V63M150 63H160" fill="none" stroke="#83a3b8" stroke-width="3"/></svg>`;}

// Read-only visual projections of the existing contracts; never advance simulation.
function contractStages(o){
 const entries=[['签约',o.acceptedDay,true],['出运',o.shipDay,!!o.paidShipping],['交付',o.deliveryDay,false],['尾款',o.dueDay,false]];
 return `<ol class="contract-stages" aria-label="合同进度">${entries.map(([label,day,done],i)=>`<li class="${done?'done':i===(o.paidShipping?2:1)?'current':''}"><span class="stage-dot">${done?'✓':i+1}</span><strong>${label}</strong><small>第 ${day} 天</small></li>`).join('')}</ol>`;
}
function tradeNetwork(){
 const open=unlockedMarkets(state),origin={x:350,y:62};
 const destinations=[{id:'asia',x:480,y:154},{id:'middle',x:245,y:154},{id:'europe',x:85,y:62}];
 const producing=state.active.filter(o=>!o.paidShipping).length,shipping=state.active.length-producing;
 return `<section class="panel trade-network"><div class="panel-head"><h2>生意在路上</h2><small>第 ${state.day} 天 · 随日期推进</small></div><div class="network-body"><div class="network-map"><svg viewBox="0 0 560 220" role="img" aria-label="出口业务示意：生产 ${producing} 单，运输 ${shipping} 单，待收尾款 ${state.receivables.length} 笔"><defs><pattern id="sea-grid" width="28" height="28" patternUnits="userSpaceOnUse"><path d="M28 0H0V28" fill="none" stroke="currentColor" stroke-width=".5"/></pattern></defs><rect width="560" height="220" fill="url(#sea-grid)" opacity=".16"/>${destinations.map(d=>{const unlocked=open.some(m=>m.id===d.id),orders=state.active.filter(o=>o.offer.market===d.id),moving=orders.filter(o=>o.paidShipping).length;return `<g class="network-destination ${unlocked?'open':'locked'}"><path class="network-route ${moving?'carrying':''}" d="M${origin.x} ${origin.y} Q${(origin.x+d.x)/2} ${Math.min(origin.y,d.y)-35} ${d.x} ${d.y}"/><circle cx="${d.x}" cy="${d.y}" r="${moving?9:6}"/><text x="${d.x}" y="${d.y+27}" text-anchor="middle">${esc(byId(MARKETS,d.id).name)}${orders.length?' · '+orders.length:''}</text><title>${unlocked?(orders.length?orders.length+' 单履约 · '+moving+' 单运输':'已开通 · 暂无在途'):'尚未开通'}</title></g>`;}).join('')}<g class="network-origin"><rect x="${origin.x-14}" y="${origin.y-14}" width="28" height="28" rx="6"/><path d="M342 66v-9h16v9M347 57v-5h6v5" fill="none" stroke="white" stroke-width="2"/><text x="${origin.x}" y="${origin.y+31}" text-anchor="middle">国内集货港</text></g></svg><small class="network-key"><i></i>运输中 <i class="idle"></i>已开通 <i class="locked"></i>未开通 · 航线示意，非实时船位</small></div><div class="flow-counts">${[['生产备货',producing,'▤'],['出口运输',shipping,'➜'],['等待尾款',state.receivables.length,'¥']].map(([label,n,icon])=>`<div class="flow-count"><span aria-hidden="true">${icon}</span><strong>${n}</strong><small>${label}</small></div>`).join('')}<div class="flow-capacity"><span>履约名额</span><b>${state.active.length} / ${capacity(state)}</b><div class="progress"><i style="width:${Math.min(100,state.active.length/capacity(state)*100)}%"></i></div></div></div></div></section>`;
}
function profitComposition(q){
 const parts=[['采购',q.cost,'purchase'],['运费',q.freight,'freight'],['锁汇费',q.fx?.fee||0,'fee'],['赔付',q.penalty||0,'penalty'],['利润',Math.max(0,q.profit),'profit']].filter(p=>p[1]>0);
 const total=parts.reduce((n,p)=>n+p[1],0)||1;
 return `<div class="profit-composition"><div class="goal-title"><strong>这单的钱去哪了</strong><small>${q.profit<0?'亏损单':q.fx?.mode==='spot'?'利润为估值':'未扣周运营费'}</small></div><div class="cost-ribbon" role="img" aria-label="${esc(parts.map(p=>p[0]+' '+money(p[1])).join('，'))}${q.profit<0?'，亏损 '+money(-q.profit):''}">${parts.map(([label,amount,kind])=>`<span class="${kind}" style="flex:${amount/total}" title="${label} ${money(amount)}"></span>`).join('')}</div><div class="cost-legend">${parts.map(([label,amount,kind])=>`<span><i class="${kind}"></i>${label}</span>`).join('')}</div>${q.profit<0?`<p class="negative">成本超过收入 ${money(-q.profit)}</p>`:''}</div>`;
}

function start(){return `<main class="start"><section><div class="wordmark">看行情，做订单，收回款</div><h1>再开一单<br>就下班</h1><p class="lead">第一单看利润，下一单看周转。<br>从一间小公司，把生意做到更远。</p><div class="start-features"><span>↗ 看行情</span><span>▤ 做订单</span><span>◷ 收回款</span><span>◈ 拓市场</span></div>${saveWarning?`<p class="notice warning">${esc(saveWarning)}</p>`:''}<form id="start-form"><label for="company-name">给你的贸易公司起个名字</label><input id="company-name" name="company" maxlength="24" value="我的贸易公司" autocomplete="off" required>${damagedSave?button('导出原存档','export-damaged'):'<button class="primary" type="submit">开张，接第一笔生意 →</button>'}</form><div class="legacy"><button class="small" data-action="import-open">导入经营存档</button></div></section><div class="scene"><h2>货走得出去，<br>钱也要回得来。</h2>${shipArt()}<p>每一笔小生意，都通向更远的地方。</p></div></main>`;}
const tabs=[['desk','经营','▤'],['market','行情','↗'],['company','公司','◈'],['ledger','账本','◷']];
function kpis(){const fc=forecastCash(state);return `<section class="kpis" aria-label="经营总览"><div class="kpi"><label>可用现金</label><strong>${money(state.cash)}</strong><small>每周运营 ${money(weeklyCost(state))}</small></div><div class="kpi"><label>42 天最低现金</label><strong class="${(fc.stressMinimum??fc.minimum)<1500?'negative':''}">${money(fc.minimum)}</strong><small>${fc.estimated?'按签约汇率估算 · 压力最低 '+money(fc.stressMinimum):'已有合同与运营费已计入'}</small></div><div class="kpi"><label>待收尾款</label><strong>${money(state.receivables.reduce((a,r)=>a+r.amount,0))}</strong><small>${state.receivables.some(r=>r.fx?.mode==='spot')?'含浮动美元尾款，按签约汇率估值':'已交付，按约定账期收回'}</small></div><div class="kpi"><label>累计订单利润</label><strong class="${state.metrics.profit>=0?'positive':'negative'}">${money(state.metrics.profit)}</strong><small>已交付 ${state.metrics.orders} 单 · ${state.receivables.some(r=>r.fx?.mode==='spot')?'含未结汇估值 · 未扣周运营费':'未扣周运营费'}</small></div></section>`;}
function shell(){const names={desk:'今天的生意',market:'商品行情',company:'公司与航线',ledger:'资金账本'};return `<div class="shell"><aside class="sidebar"><div class="brand">再开一单<br>就下班</div><div class="company-stamp"><small>一家认真做生意的公司</small><strong>${esc(state.name)}</strong><small>${unlockedMarkets(state).length} 个市场 · ${state.metrics.orders} 笔交付</small></div><nav>${tabs.map(([id,name,icon])=>button(`<span>${icon}</span>${name}`,'tab',`data-tab="${id}"`,tab===id?'active':'')).join('')}</nav><div class="foot"><span>资金流转，生意向前。</span><button class="small" data-action="export">导出经营存档</button></div></aside><main class="workspace"><header class="topbar"><div><div class="eyebrow">${esc(state.name)} / ${state.ending?'继续远航':'第一程'}</div><h1>${names[tab]}</h1></div><div class="top-actions"><span class="week">第 <b>${state.day}</b> 天<small>第 ${state.week} 周</small></span><div class="time-controls">${button('下一天 →','next','', 'primary')}${button('快进 3 天','advance',`data-days="3" title="最多前往第 ${state.day+3} 天，重要事项会暂停"`,'small')}${button('到下一节点','next-event',nextTradeEvent(state)?'':'disabled','small')}${button('快进 7 天','advance',`data-days="7" title="最多前往第 ${state.day+7} 天，重要事项会暂停"`,'small')}</div></div></header>${saveWarning?`<div class="notice warning">${esc(saveWarning)}</div>`:''}${notice?`<div class="notice"><span>${esc(notice)}</span>${button('×','dismiss','aria-label="关闭提示"')}</div>`:''}${tab!=='desk'||lastAdvance?.pause?advanceFeedback():''}${tab==='desk'?`<section class="cash-strip"><div><small>手头的钱</small><strong>${money(state.cash)}</strong></div><div><small>交付赚到的利润</small><strong>${money(state.metrics.profit)}</strong></div><small>利润含待收尾款，未扣运营费 · ${button('看账本','tab','data-tab="ledger"','small')}</small></section>`:kpis()}${tab==='desk'?'':receiptFeedback()}${tab==='desk'?'':nextMilestone()}${({desk:desk,market:market,company:company,ledger:ledger})[tab]()}<footer class="life-dock" aria-label="生活">${lifePanel()}</footer></main><nav class="mobile-nav" aria-label="主导航">${tabs.map(([id,name,icon])=>button(`<span>${icon}</span>${name}`,'tab',`data-tab="${id}"`,tab===id?'active':'')).join('')}</nav></div>`;}
function goals(){const markets=unlockedMarkets(state);const covered=new Set(Object.values(state.customers).map(c=>c.market)).size;const worth=netWorth(state);return `<div class="panel"><div class="panel-head"><h2>${state.ending?'航线已成，继续远航':'下一程：三大市场'}</h2><span class="pill">已履约 ${covered}/3</span></div><div class="goal">${[['市场入场交付',state.metrics.orders,8,'单'],['公司净值',Math.max(0,worth),60000,''],['信誉',state.reputation,8,'']].map(([name,n,max,unit])=>`<div class="goal-title"><span>${name}</span><strong>${name==='公司净值'?money(n):n}${unit} / ${name==='公司净值'?money(max):max}${unit}</strong></div><div class="progress"><i style="width:${Math.min(100,n/max*100)}%"></i></div>`).join('')}<div class="goal-title"><span>欧洲框架试单</span><strong>${state.customers['europe-flagship']?.qualified?'已合格交付':europeanTrackRecord(state)?'已具备试单资格':'先完成欧洲普通客户交付'}</strong></div>${!state.ending?`<p class="goal-gap">${worth<60000?'净值还差 '+money(60000-worth):'净值目标已达成'} · ${covered<3?'还需履约 '+(3-covered)+' 个市场':'三大市场已履约'}</p>`:''}${!state.ending&&worth>=60000&&covered===3&&state.customers['europe-flagship']?.qualified?'<small>目标已具备，完成下一笔交付或回款时结算第一程。</small>':''}${state.ending?'<small>第一程目标已全部达成。可以继续接单、拓展公司，或到生活里享受经营成果；这些都不影响已有通关成绩。</small>':(state.customers['europe-flagship']?.qualified?'<small>欧洲框架试单已经合格，继续经营补齐上方尚未达成的目标。</small>':'<small>试单要求：品质 95、21 天交付、15% 订金。先准备验货与周转能力。</small>')+'<small>3 单解锁中东，8 单且信誉 8 解锁欧洲。实际交付覆盖三大市场、净值 6 万，并合格完成欧洲框架试单，完成第一程。</small>'}</div></div>`;}
function receiptFeedback(){
 if(!lastReceipt)return '';
 const r=lastReceipt;
 if(r.day<state.day)return `<details class="receipt-history"><summary>${dayLabel(r.day)} · 历史经营回执</summary>${receiptBody(r)}</details>`;
 return receiptBody(r);
}
function pendingTails(){
 if(!state.receivables.length)return '';
 return `<div class="pending-tails"><strong>利润不等于现金 · 待收尾款</strong>${state.receivables.map(r=>`<p>${esc(r.customer)}：${money(r.amount)} · 第 ${r.dueDay} 天到账${r.fx?.mode==='spot'?'（浮动结汇估值）':''} ${button('跟进这笔回款 →','follow-order',`data-id="${esc(r.id)}"`,'small')}</p>`).join('')}</div>`;
}
function receiptBody(r){
 return `<section class="receipt" role="status"><div><small>${dayLabel(r.day)} · 经营回执</small>${r.frameworkQualified?'<p class="framework-earned"><strong>欧洲框架试单合格</strong><span>品质与交期都兑现了，这条航线站稳了。</span></p>':''}${r.firstMarkets?.includes('europe')&&!r.frameworkQualified?'<p class="positive">欧洲首单兑现 · 已具备框架邀约资格</p>':''}${r.firstMarkets?.length?`<p class="positive"><strong>新航线首单达成 · ${r.firstMarkets.map(id=>esc(byId(MARKETS,id).name)).join(' / ')}</strong></p>`:''}<h2>${r.orders?r.orders+' 笔交付':'货款到账'}${r.orders?' · 订单利润 '+(r.profit>=0?'+':'')+money(r.profit):''}</h2><p>本次尾款入账 <b class="positive">${money(r.receipts)}</b> · 本次现金净变化 ${r.cash>=0?'+':''}${money(r.cash)}${r.reputation?' · 信誉 +'+r.reputation:''}${r.markets?' · 解锁 '+r.markets+' 个新市场':''}</p><details class="receipt-cash"><summary>现金为什么这样变化？</summary><p>本段尾款 +${money(r.receipts)}，出运支出 −${money(r.payments||0)}，运营与利息 −${money(r.operating||0)}。订金在签约时已计入现金，不在此重复计算。</p></details>${state.receivables.length?`<details class="receipt-tails"><summary>查看 ${state.receivables.length} 笔待收尾款</summary>${pendingTails()}</details>`:''}${r.estimated?'<small>利润含浮动尾款估值，结汇后确定。</small>':''}</div>${button('收好','receipt-dismiss','','small')}</section>`;
}
function nextMilestone(){
 const next=nextTradeEvent(state);
 if(!next)return '';
 return `<div class="next-milestone"><strong>下一节点：${esc(next.label)} · ${dayLabel(next.day)}</strong><span>${esc(next.customer)} · 还需 ${Math.max(0,next.day-state.day)} 天${state.active.length>=capacity(state)?' · 订单名额已满，可快进等履约':''}</span></div>`;
}
function forecastTable(points){return `<div class="scroll-table"><table class="ledger-table"><thead><tr><th>日期</th><th>入账</th><th>支出含运营</th><th>期末现金</th></tr></thead><tbody>${points.map(p=>`<tr><td>${dayLabel(p.day)}${p.day===state.day?' · 当前':''}</td><td class="positive">${money(p.inflow)}</td><td>${money(p.outflow)}</td><td class="${p.cash<0?'negative':''}">${money(p.cash)}</td></tr>`).join('')}</tbody></table></div>`;}
function forecastSummary(fc){
 const events=fc.points.filter(p=>p.day===state.day||p.inflow||p.outflow);
 const scale=Math.max(1,...events.flatMap(p=>[p.inflow,p.outflow]));
 return `<div class="cash-calendar" role="img" aria-label="未来收支日历，所有柱条使用同一金额尺度"><div class="cash-key"><span><i class="cash-in"></i>回款</span><span><i class="cash-out"></i>支出含运营</span></div>${events.map(p=>`<div class="cash-day"><strong>${dayLabel(p.day)}</strong><div class="cash-bars"><div><i class="cash-in" style="width:${p.inflow/scale*100}%"></i><span>${p.inflow?'+'+money(p.inflow):'无回款'}</span></div><div><i class="cash-out" style="width:${p.outflow/scale*100}%"></i><span>${p.outflow?'−'+money(p.outflow):'无支出'}</span></div></div><span class="cash-balance ${p.cash<0?'negative':''}"><small>结余</small>${money(p.cash)}</span></div>`).join('')}</div><details class="forecast-details"><summary>查看全部 ${fc.points.length} 天明细（含无收支日）</summary>${forecastTable(fc.points)}</details>`;
}
function nextAdvice(){
 const fc=forecastCash(state),minimum=fc.stressMinimum??fc.minimum,next=nextTradeEvent(state);
 if(minimum<0)return {title:'先稳住周转',reason:'已有合同的后续支出可能让现金不足。先看账本里的周转工具，再决定接不接新单。',action:'tab',attrs:'data-tab="ledger"',label:'查看账本'};
 if(state.active.length>=capacity(state)&&next)return {title:'先把手里的单做完',reason:`履约名额已满；${next.label}还要 ${Math.max(0,next.day-state.day)} 天。推进不会替你接新单。`,action:'next-event',attrs:'',label:'到下一节点'};
 if(state.receivables.length&&(state.cash<5000||state.receivables.reduce((n,r)=>n+r.amount,0)>state.cash)&&next)return {title:'利润还在客户那里',reason:`手头 ${money(state.cash)}，另有 ${money(state.receivables.reduce((n,r)=>n+r.amount,0))} 尾款未收。可等回款保周转，也可挑不压资金的小单。`,action:'follow-order',attrs:`data-id="${esc([...state.receivables].sort((a,b)=>a.dueDay-b.dueDay)[0].id)}"`,label:'等最近一笔回款'};
 const entry=state.offers.find(o=>o.market==='europe'&&o.kind!=='flagship');
 if(entry&&!europeanTrackRecord(state)&&!state.customers['europe-flagship']?.qualified&&!state.active.some(o=>o.offer.market==='europe')){const q=quoteOrder(state,entry.id);if(q.valid&&forecastCash(state,q).stressMinimum>=0)return {title:'先在欧洲交出第一单',reason:`普通客户履约后才有框架邀约。这笔要求品质 ${entry.quality}，${entry.payLagDays?'交付后还要等 '+entry.payLagDays+' 天回款':'交付就收齐尾款'}；先比较方案，不必急着接。`,action:'quote',attrs:`data-id="${esc(entry.id)}"`,label:'比较欧洲首单'};}
 const trial=state.offers.find(o=>o.kind==='flagship');
 if(trial&&!state.customers['europe-flagship']?.qualified){
  const q=quoteOrder(state,trial.id,{supplier:'express',shipping:'rail',markup:0,fxMode:'locked',paymentTerms:'standard'});
  if(q.quality<trial.quality&&state.upgrades.quality<byId(UPGRADES,'quality').max)return {title:'大客户先看交付质量',reason:`试单要求品质 ${trial.quality}，当前快运方案为 ${q.quality}。驻厂验货能改善品质，但投入 ${money(upgradeCost(state,'quality'))} 后仍要留足合同周转。`,action:'upgrade',attrs:'data-id="quality"',label:'比较验货投入'};
  const trialForecast=forecastCash(state,q),trialMinimum=trialForecast.stressMinimum??trialForecast.minimum;
  if(trialMinimum<0&&state.receivables.length){const r=[...state.receivables].sort((a,b)=>a.dueDay-b.dueDay)[0];return {title:'先给框架单备足周转',reason:`当前快运方案42天现金底 ${money(trialMinimum)}，还不能安全接。最近一笔 ${money(r.amount)} 尾款在第 ${r.dueDay} 天到账；可以先等它，或另选更高订金的方案。`,action:'follow-order',attrs:`data-id="${esc(r.id)}"`,label:'跟进最近回款'};}
  if(trialMinimum<0){const bridge=state.offers.filter(o=>o.id!==trial.id).map(o=>({o,q:quoteOrder(state,o.id,{supplier:'reliable',shipping:o.deadlineDays<28?'rail':'sea'})})).find(({q})=>q.valid&&q.profit>0&&(forecastCash(state,q).stressMinimum??forecastCash(state,q).minimum)>=0);return bridge?{title:'框架单先缓一缓',reason:`试单快运方案还缺 ${money(-trialMinimum)} 周转。${byId(PRODUCTS,bridge.o.product).name}这笔订金 ${bridge.o.depositRate}%，可先比较它；扩张资产不能拿来付货款。`,action:'quote',attrs:`data-id="${esc(bridge.o.id)}"`,label:'比较能周转的小单'}:{title:'先给框架单留出现金',reason:`试单快运方案还缺 ${money(-trialMinimum)} 周转，眼前其他询盘也不宜直接接。可以看周转工具，或等下一批机会，不必为了试单立即借款。`,action:'tab',attrs:'data-tab="ledger"',label:'查看周转工具'};}
  return {title:'试试欧洲框架单',reason:`这次要品质 ${trial.quality}、${trial.deadlineDays} 天内交付；符合要求才算通过。别只看利润，先比较方案和周转。`,action:'quote',attrs:`data-id="${esc(trial.id)}"`,label:'看看试单'};
 }
 if(state.offers.length){const candidate=state.offers.map(o=>({o,q:quoteOrder(state,o.id)})).find(({q})=>q.valid&&q.profit>0&&(forecastCash(state,q).stressMinimum??forecastCash(state,q).minimum)>=0);if(candidate)return {title:state.ending?'下一单可以挑着做':'有一笔值得比较的机会',reason:`${byId(PRODUCTS,candidate.o.product).name}基准方案预计赚 ${money(candidate.q.profit)}${candidate.q.penalty?'，但有交期或品质赔付，先换方案比较':'；利润更高的报价也更容易被拒绝'}。`,action:'quote',attrs:`data-id="${esc(candidate.o.id)}"`,label:'比较方案'};return {title:'不必每单都接',reason:'眼前机会的基准方案不理想。可以先看行情，再决定调方案还是等下一批。',action:'tab',attrs:'data-tab="market"',label:'看看行情'};}
 return {title:state.ending?'这一程已经完成':'等下一批生意',reason:next?`下一件事是${next.label}，还有 ${Math.max(0,next.day-state.day)} 天。`:'当前没有可接询盘，推进日期等待新的机会。',action:next?'next-event':'next',attrs:'',label:next?'到下一节点':'下一天'};
}
function advisor(){const a=nextAdvice();return `<section class="advisor"><div>${button(advisorOpen?'收起建议':'问问顾问','advisor-toggle','','small')}<small>${advisorOpen?'建议供你选择，不自动操作':''}</small></div>${advisorOpen?`<div class="advisor-body"><strong>${a.title}</strong><p>${esc(a.reason)}</p>${button(a.label,a.action,a.attrs,'small')}</div>`:''}</section>`;}
function shippingGroups(){
 const groups=new Map();
 for(const o of state.active.filter(o=>o.paidShipping)){
  const progress=Math.max(0,Math.min(.999,(state.day-o.shipDay)/Math.max(1,o.deliveryDay-o.shipDay))),stage=Math.min(2,Math.floor(progress*3)),key=o.offer.market+'-'+stage;
  if(!groups.has(key))groups.set(key,{key,market:o.offer.market,stage,orders:[]});groups.get(key).orders.push(o);
 }
 return [...groups.values()];
}
