 if(m==='asia')return `<path d="M783 ${y+55}v-38h58v38" fill="#ebd9b8"/><path d="M776 ${y+17}h72l-7-12h-58z" fill="#dc9568"/>${[0,1,2,3].map(i=>`<path d="M${779+i*17} ${y+17}v9h14v-9" fill="${i%2?'#f4e8d1':'#4e8d82'}"/>`).join('')}<rect x="791" y="${y+33}" width="17" height="22" fill="#718e87"/><rect x="817" y="${y+33}" width="16" height="14" fill="#b4cdc2"/>`;
