 return `<path d="M777 ${y+55}v-44h68v44" fill="#c1d1d8"/><path d="M772 ${y+11}l20-20 15 20 19-20 24 20" fill="#536c7c"/>${[0,1,2].map(i=>`<rect x="${784+i*20}" y="${y+23}" width="12" height="17" fill="#7195a3"/>`).join('')}<rect x="801" y="${y+42}" width="20" height="13" fill="#415f65"/>`;
